// Build Product Documents (one per active product row)
const items = $input.all();
const out = [];
for (const it of items) {
  const p = it.json;
  const status = (p.status || '').toString().trim().toLowerCase();
  if (status && status !== 'active') continue;
  const name = (p.name || '').toString().trim();
  if (!name) continue;
  const id = (p.product_id || `prd-${out.length+1}`).toString().trim();
  const lines = [
    `Type: product`,
    `Product: ${name}`,
    `Category: ${p.category || ''}`,
    `Available sizes: ${p.size || ''}`,
    `Available colors: ${p.color || ''}`,
    `Price (BDT): ${p.price ?? ''}`,
    `Stock: ${p.stock ?? ''}`,
    `Description: ${p.description || ''}`,
  ].filter(l => (l.split(': ')[1] || '').toString().trim() !== '');
  out.push({ json: {
    content: lines.join('\n'),
    metadata: {
      id: `product-${id}`,
      source: 'products_sheet',
      type: 'product',
      product_id: id,
      name: name,
      category: (p.category || '').toString()
    }
  }});
}
return out;

// Build FAQ Documents
const items = $input.all();
const out = [];
for (const it of items) {
  const f = it.json;
  const q = (f.question || '').toString().trim();
  const a = (f.answer || '').toString().trim();
  if (!q || !a) continue;
  const status = (f.status || '').toString().trim().toLowerCase();
  if (status && status !== 'active') continue;
  const id = (f.faq_id || f.id || `faq-${out.length+1}`).toString().trim();
  const cat = (f.category || '').toString().trim();
  const lines = [
    `Type: faq`,
    cat ? `Category: ${cat}` : '',
    `Question: ${q}`,
    `Answer: ${a}`,
  ].filter(Boolean);
  out.push({ json: {
    content: lines.join('\n'),
    metadata: {
      id: `faq-${id}`,
      source: 'faq_sheet',
      type: 'faq',
      faq_id: id,
      category: cat
    }
  }});
}
return out;

// Build Size_Guide Documents
const items = $input.all();
const out = [];
const META_KEYS = new Set(['size_id','id','category','product_category',
  'size','status','notes','created_at','updated_at']);
for (const it of items) {
  const s = it.json;
  const cat = (s.category || s.product_category || '').toString().trim();
  const size = (s.size || '').toString().trim();
  if (!cat && !size) continue;
  const status = (s.status || '').toString().trim().toLowerCase();
  if (status && status !== 'active') continue;
  const sid = (s.size_id || s.id || `${cat||'na'}-${size||out.length+1}`).toString().trim();
  // Pull any measurement-like fields
  const measures = Object.keys(s)
    .filter(k => !META_KEYS.has(k))
    .map(k => {
      const v = s[k];
      if (v === null || v === undefined || v === '') return '';
      return `${k}: ${v}`;
    })
    .filter(Boolean)
    .join(', ');
  const notes = (s.notes || '').toString().trim();
  const lines = [
    `Type: size_guide`,
    cat ? `Category: ${cat}` : '',
    size ? `Size: ${size}` : '',
    measures ? `Measurements: ${measures}` : '',
    notes ? `Notes: ${notes}` : '',
  ].filter(Boolean);
  out.push({ json: {
    content: lines.join('\n'),
    metadata: {
      id: `size-${sid}`,
      source: 'size_guide_sheet',
      type: 'size_guide',
      size_id: sid,
      category: cat,
      size: size
    }
  }});
}
return out;

// Build Sales_Objection Documents
const items = $input.all();
const out = [];
for (const it of items) {
  const o = it.json;
  const obj  = (o.objection || o.question || '').toString().trim();
  const resp = (o.response || o.answer || o.reply || '').toString().trim();
  if (!obj || !resp) continue;
  const status = (o.status || '').toString().trim().toLowerCase();
  if (status && status !== 'active') continue;
  const id  = (o.objection_id || o.id || `obj-${out.length+1}`).toString().trim();
  const cat = (o.category || '').toString().trim();
  const lines = [
    `Type: objection`,
    cat ? `Category: ${cat}` : '',
    `Objection: ${obj}`,
    `Response: ${resp}`,
  ].filter(Boolean);
  out.push({ json: {
    content: lines.join('\n'),
    metadata: {
      id: `objection-${id}`,
      source: 'sales_objections_sheet',
      type: 'objection',
      objection_id: id,
      category: cat
    }
  }});
}
return out;

// Build Instruction Documents (from Setup / Instructions sheet)
// SECURITY: skip secrets/tokens — only operational rules go to RAG.
const items = $input.all();
const out = [];
const SECRET_RX = /(token|secret|password|api[_ ]?key|sheet[_ ]?id|chat[_ ]?id)/i;
const ALLOW_RX  = /(reply|style|memory|max|tone|language|hour|policy|rule|instruction|behavior|prompt)/i;
for (const it of items) {
  const s = it.json;
  const key = (s.key || '').toString().trim();
  const val = (s.value || '').toString().trim();
  if (!key || !val) continue;
  // Block secrets unless explicitly allow-listed
  if (SECRET_RX.test(key) && !ALLOW_RX.test(key)) continue;
  const notes = (s.notes || '').toString().trim();
  const stableId = key.toLowerCase().replace(/[^a-z0-9]+/g,'_');
  const lines = [
    `Type: instruction`,
    `Setting: ${key}`,
    `Value: ${val}`,
    notes ? `Notes: ${notes}` : '',
  ].filter(Boolean);
  out.push({ json: {
    content: lines.join('\n'),
    metadata: {
      id: `instruction-${stableId}`,
      source: 'setup_sheet',
      type: 'instruction',
      key: key
    }
  }});
}
return out;
